export function buildCardArchiveMoves(
    files: MarkdownFile[],
    archivedCards: Card[],
    targetFolder: string,
    repositoryFiles: string[] = [],
): MoveFile[] {
    const existingPaths = new Set([
        ...files.map((file) => normalizePath(file.path)),
        ...repositoryFiles.map(normalizePath),
    ])
    const filesByPath = new Map(files.map((file) => [normalizePath(file.path), file]))
    const archiveAssetPaths = new Set(findArchiveAssetPaths(files, archivedCards))
    const archivedAssetTargets = new Map<string, string>()
    const moveTargetPaths = new Set<string>()
    const moves: MoveFile[] = []

    for (const card of archivedCards) {
        const sourcePath = normalizePath(card.path)
        const toPath = targetPathForSource(targetFolder, sourcePath)

        if (existingPaths.has(toPath) || moveTargetPaths.has(toPath)) throw new Error(`Archive target already exists: ${toPath}`)
        const file = filesByPath.get(sourcePath)
        if (!file) throw new Error(`Cannot archive unloaded card file: ${card.path}`)

        moveTargetPaths.add(toPath)
        moves.push(createMove(file, card.path, toPath))

        const cardAssetPaths = allReferencedCardAssets(file, referencedCopiedAssets(card.header.references))
        for (const assetPath of cardAssetPaths.map(normalizePath)) {
            if (!archiveAssetPaths.has(assetPath)) continue

            const assetTargetPath = targetPathForSource(targetFolder, assetPath)
            if (existingPaths.has(assetTargetPath) || moveTargetPaths.has(assetTargetPath)) {
                throw new Error(`Archive target already exists: ${assetTargetPath}`)
            }

            const assetFile = filesByPath.get(assetPath)
            if (!assetFile) throw new Error(`Cannot archive unloaded card asset: ${assetPath}`)

            moveTargetPaths.add(assetTargetPath)
            moves.push(createMove(assetFile, assetPath, assetTargetPath, 'base64'))
            archivedAssetTargets.set(assetPath, assetTargetPath)
            archiveAssetPaths.delete(assetPath)
        }
    }

    for (const card of archivedCards) {
        const cardMove = moves.find((move) => normalizePath(move.fromPath) === normalizePath(card.path))
        if (!cardMove) continue

        const rewrittenReferences = card.header.references.map((reference) => (
            isAbsoluteAssetReference(reference)
                ? reference
                : archivedAssetTargets.get(normalizePath(reference)) ?? reference
        ))
        const hasRewrittenReference = rewrittenReferences.some((reference, index) => reference !== card.header.references[index])
        if (hasRewrittenReference) cardMove.content = markdownParsingService.setReferences(cardMove.content, rewrittenReferences)
    }

    return moves
}

import { Button, Dialog, DialogActions, DialogContent, DialogTitle, Stack, TextField, Typography } from '@mui/material'
import type { ChangeEvent } from 'react'
import { useState } from 'react'
import type { ReleaseBranchCandidate } from '../../../data/data_types'
import { ReleaseBranchCheckbox } from './release_branch_checkbox'

interface CompleteReleaseDialogProps {
    branchCandidates: ReleaseBranchCandidate[]
    defaultSelectAll: boolean
    isLoading: boolean
    open: boolean
    onClose: () => void
    onCompleteRelease: (releaseName: string, selectedBranchNames: string[]) => Promise<void>
    onSelectAllDefaultChange: (selected: boolean) => void
}

/** Dialog for confirming and naming release completion. */
export function CompleteReleaseDialog(props: CompleteReleaseDialogProps) {
    const { branchCandidates, defaultSelectAll, isLoading, onClose, onCompleteRelease, onSelectAllDefaultChange, open } = props
    const [releaseName, setReleaseName] = useState('')
    const [selectedBranchNames, setSelectedBranchNames] = useState<Set<string>>(
        defaultSelectAll ? new Set(branchCandidates.map(({ branchName }) => branchName)) : new Set(),
    )

    const handleReleaseNameChange = (event: ChangeEvent<HTMLInputElement>) => {
        setReleaseName(event.target.value)
    }

    const handleCompleteClick = async () => {
        if (releaseName.length === 0) return

        const selectedBranches = branchCandidates
            .map(({ branchName }) => branchName)
            .filter((branchName) => selectedBranchNames.has(branchName))
        await onCompleteRelease(releaseName, selectedBranches)
        setReleaseName('')
    }
    const handleBranchChange = (branchName: string, checked: boolean) => {
        const nextSelectedBranchNames = new Set(selectedBranchNames)
        if (checked) nextSelectedBranchNames.add(branchName)
        else nextSelectedBranchNames.delete(branchName)
        setSelectedBranchNames(nextSelectedBranchNames)
    }
    const handleSelectAll = () => {
        setSelectedBranchNames(new Set(branchCandidates.map(({ branchName }) => branchName)))
        onSelectAllDefaultChange(true)
    }
    const handleClearAll = () => {
        setSelectedBranchNames(new Set())
        onSelectAllDefaultChange(false)
    }

    return (
        <Dialog fullWidth maxWidth="xs" onClose={onClose} open={open}>
            <DialogTitle>Complete release</DialogTitle>
            <DialogContent>
                <Stack spacing={2} sx={{ pt: 1 }}>
                    <TextField label="Release name" onChange={handleReleaseNameChange} size="small" value={releaseName} />
                    {branchCandidates.length > 0 ? (
                        <Stack spacing={1}>
                            <Typography color="text.secondary">Delete local branches</Typography>
                            <Stack direction="row" spacing={1}>
                                <Button disabled={isLoading} onClick={handleSelectAll} size="small">Select all</Button>
                                <Button disabled={isLoading} onClick={handleClearAll} size="small">Clear all</Button>
                            </Stack>
                            {branchCandidates.map((candidate) => (
                                <ReleaseBranchCheckbox
                                    candidate={candidate}
                                    checked={selectedBranchNames.has(candidate.branchName)}
                                    disabled={isLoading}
                                    key={candidate.branchName}
                                    onChange={handleBranchChange}
                                />
                            ))}
                        </Stack>
                    ) : null}
                </Stack>
            </DialogContent>
            <DialogActions>
                <Button onClick={onClose}>Cancel</Button>
                <Button disabled={releaseName.length === 0 || isLoading} onClick={handleCompleteClick} variant="contained">
                    Complete release
                </Button>
            </DialogActions>
        </Dialog>
    )
}

const ACTIVITY_ID_PATTERN = /^[a-zA-Z0-9._-]+$/u

function normalizeFolderPath(folderPath) {
    return folderPath.replace(/\\/gu, '/').replace(/^\/+|\/+$/gu, '')
}

function requireActivityId(value, fieldName) {
    if (typeof value !== 'string' || value.length === 0) throw new Error(`Missing ${fieldName}`)
    if (!ACTIVITY_ID_PATTERN.test(value) || value === '.' || value === '..') throw new Error(`Invalid ${fieldName}: ${value}`)

    return value
}

export function projectActivityFolder(projectFolder) {
    if (typeof projectFolder !== 'string') throw new Error('Missing projectFolder')
    const normalizedProjectFolder = normalizeFolderPath(projectFolder)

    return normalizedProjectFolder.length > 0 ? `${normalizedProjectFolder}/activity` : 'activity'
}

export function cardActivityFileName(cardInternalId) {
    return `card__${requireActivityId(cardInternalId, 'cardInternalId')}.json`
}

export function projectActivityFileName() {
    return 'project.json'
}

export function activityFilePath(projectFolder, origin) {
    if (!origin || typeof origin !== 'object') throw new Error('Missing activity origin')
    const fileName = origin.kind === 'card'
        ? cardActivityFileName(origin.cardInternalId)
        : origin.kind === 'project' ? projectActivityFileName() : null
    if (!fileName) throw new Error(`Invalid activity origin kind: ${String(origin.kind)}`)

    return `${projectActivityFolder(projectFolder)}/${fileName}`
}

/** Derive canonical activity ownership from a recognized activity filename. */
export function activityOriginFromPath(activityPath) {
    if (typeof activityPath !== 'string' || activityPath.length === 0) return null
    const fileName = activityPath.replace(/\\/gu, '/').split('/').pop()
    if (fileName === projectActivityFileName()) return { kind: 'project' }
    const match = /^card__(.+)\.json$/u.exec(fileName ?? '')
    if (!match || !ACTIVITY_ID_PATTERN.test(match[1]) || match[1] === '.' || match[1] === '..') return null

    return { cardInternalId: match[1], kind: 'card' }
}

export function conversationActivityReference(activityPath, conversationId) {
    if (typeof activityPath !== 'string' || activityPath.length === 0) throw new Error('Missing activity path')
    const id = requireActivityId(conversationId, 'conversationId')

    return `${activityPath}#conversation=${id}`
}

export function parseConversationActivityReference(reference) {
    if (typeof reference !== 'string' || reference.length === 0) throw new Error('Missing conversation activity reference')
    const marker = '#conversation='
    const markerIndex = reference.lastIndexOf(marker)
    if (markerIndex <= 0) throw new Error(`Invalid conversation activity reference: ${reference}`)
    const activityPath = reference.slice(0, markerIndex)
    const conversationId = requireActivityId(reference.slice(markerIndex + marker.length), 'conversationId')

    return { activityPath, conversationId }
}

