    const normalizedProjectFolder = projectFolder.replace(/\\/gu, '/').replace(/^\/+|\/+$/gu, '')

    return normalizedProjectFolder.length > 0
        ? `${normalizedProjectFolder}/${AGENT_TOKEN_USAGE_FILE_NAME}`
        : AGENT_TOKEN_USAGE_FILE_NAME
}

